/** A retained mutation workspace must end before a failed writer is aborted and replayed. */
class LmdbPersistentAdjacencyBatchReplayTest {

	@TempDir
	Path directory;

	@Test
	@Timeout(60)
	void mapFullClosesTheLiveBatchCursorBeforeAbortAndReplaysTheWholeLogicalBatch() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setAutoGrow(true)
				.setForceSync(true)
				.setSketchEstimatorEnabled(false)
				.setTripleDBSize(8L << 20);
		Set<List<Long>> expected = new HashSet<>();
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			store.startTransaction();
			for (int row = 0; row < 128; row++) {
				long subject = 1000L + row;
				long object = 5000L + 2L * row;
				assertThat(store.storeTriple(subject, 20, object, 0, true)).isTrue();
				expected.add(List.of(subject, 20L, object, 0L));
			}
			assertThat(store.storeTriple(2000, 20, 9000, 7, false)).isTrue();
			assertThat(store.storeTriple(2001, 20, 9002, 9, false)).isTrue();
			store.commit();

			try (Txn pinned = store.getTxnManager().createReadTxnPinned(store::getDataRevision);
					RecordIterator oldRows = store.getTriples(pinned, -1, -1, -1, -1, true)) {
				assertThat(oldRows.next()).containsExactly(1000, 20, 5000, 0);
				store.startTransaction();
				// A successful prefix precedes this batch in the same journal. Replay must retain it without
				// inventing another caller callback for it.
				assertThat(store.storeTriple(9000, 30, 9001, 7, true)).isTrue();
				expected.add(List.of(9000L, 30L, 9001L, 7L));
				long failedWriter = store.writeTxn;
				long originalMapSize = store.mapSizeBytes();
				LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(failedWriter);
				int pages = adjacency.pagesDbi();
				int metadata = adjacency.metadataDbi();
				int deltas = adjacency.deltasDbi();
				Set<Long> liveWriterPageCursors = new HashSet<>();
				Set<Long> liveWriterMetadataCursors = new HashSet<>();
				AtomicBoolean injected = new AtomicBoolean();
				AtomicBoolean aborted = new AtomicBoolean();
				AtomicInteger outgoingWrites = new AtomicInteger();
				List<String> events = new ArrayList<>();
				List<Integer> added = new ArrayList<>();
				long[][] input = batchInput();
				for (int row : new int[] { 0, 1, 2, 3, 4, 6 }) {
					expected.add(List.of(input[0][row], input[1][row], input[2][row], input[3][row]));
				}

				try (MockedStatic<LMDB> ignored = mockStatic(LMDB.class, invocation -> {
					String method = invocation.getMethod().getName();
					if (method.equals("mdb_cursor_open")) {
						Object result = invocation.callRealMethod();
						if ((int) result == MDB_SUCCESS && !aborted.get()
								&& (long) invocation.getArgument(0) == failedWriter) {
							PointerBuffer handle = invocation.getArgument(2);
							int database = invocation.getArgument(1);
							if (database == pages) {
								assertThat(liveWriterPageCursors.add(handle.get(0))).isTrue();
							} else if (database == metadata) {
								assertThat(liveWriterMetadataCursors.add(handle.get(0))).isTrue();
							}
						}
						return result;
					}
					if (method.equals("mdb_cursor_close")) {
						long cursor = invocation.getArgument(0);
						Object result = invocation.callRealMethod();
						if (liveWriterPageCursors.remove(cursor)) {
							events.add("cursor-close");
						}
						if (liveWriterMetadataCursors.remove(cursor)) {
							events.add("metadata-cursor-close");
						}
						return result;
					}
					if (method.equals("mdb_put") && !injected.get()
							&& (long) invocation.getArgument(0) == failedWriter
							&& (int) invocation.getArgument(1) == deltas) {
						MDBVal key = invocation.getArgument(2);
						if (key.mv_size() == 33 && key.mv_data().get(0) == 0
								&& outgoingWrites.incrementAndGet() == 3) {
							boolean insideBatch = StackWalker.getInstance()
									.walk(frames -> frames.anyMatch(frame -> frame.getClassName()
											.equals(LmdbPersistentAdjacency.MutationBatch.class.getName())
											&& frame.getMethodName().equals("add")));
							assertThat(insideBatch)
									.as("the failure must occur inside the retained physical batch")
									.isTrue();
							assertThat(liveWriterPageCursors).as("the retained page cursor is live at the fault")
									.hasSize(1);
							assertThat(liveWriterMetadataCursors)
									.as("the retained metadata cursor is live at the fault")
									.hasSize(1);
							// This cached old snapshot still sees only committed base rows immediately before growth.
							assertThat(oldRows.next()).containsExactly(1001, 20, 5002, 0);
							injected.set(true);
							events.add("fault");
							return MDB_MAP_FULL;
						}
					}
					if (method.equals("mdb_txn_abort") && injected.get() && !aborted.get()
							&& (long) invocation.getArgument(0) == failedWriter) {
						assertThat(liveWriterPageCursors).as("close writer cursors before aborting their transaction")
								.isEmpty();
						assertThat(liveWriterMetadataCursors)
								.as("close metadata cursors before aborting their transaction")
								.isEmpty();
						events.add("abort");
						// Native transaction addresses may be reused by the replay writer; stop tracking this owner.
						aborted.set(true);
					}
					if (method.equals("mdb_env_set_mapsize") && injected.get()) {
						assertThat(aborted.get()).as("abort the failed writer before remapping").isTrue();
						assertThat(liveWriterPageCursors).isEmpty();
						assertThat(liveWriterMetadataCursors).isEmpty();
						events.add("map-resize");
					}
					return invocation.callRealMethod();
				})) {
					store.storeTriplesAligned(input[0], input[1], input[2], input[3], input[0].length,
							true, false, index -> {
								assertThat(aborted.get()).isTrue();
								assertThat(liveWriterPageCursors).isEmpty();
								assertThat(liveWriterMetadataCursors).isEmpty();
								added.add(index);
							});
				}

				assertThat(injected.get()).isTrue();
				assertThat(outgoingWrites.get()).isEqualTo(3);
				assertThat(events).containsSubsequence("fault", "cursor-close", "abort", "map-resize");
				assertThat(events).containsSubsequence("fault", "metadata-cursor-close", "abort", "map-resize");
				assertThat(store.mapSizeBytes()).isGreaterThan(originalMapSize);
				assertThat(added).containsExactly(0, 1, 2, 3, 4, 6);
				assertState(LmdbPersistentAdjacency.openExisting(store.writeTxn), store.writeTxn, expected);
				assertThatThrownBy(oldRows::next).isInstanceOf(LmdbSailStore.MapResizeConflictException.class)
						.hasMessageContaining("memory map was resized");
				store.commit();
			}
			assertCommittedState(store, expected);
		}

		try (TripleStore reopened = new TripleStore(directory.toFile(), config, null)) {
			assertCommittedState(reopened, expected);
		}
	}

	private static long[][] batchInput() {
		long[][] input = new long[4][8];
		for (int row = 0; row < 5; row++) {
			input[0][row] = 1000L + row;
			input[1][row] = 20;
			input[2][row] = 5001L + 2L * row;
		}
		input[0][6] = 2000;
		input[1][6] = 20;
		input[2][6] = 9000;
		input[3][6] = 7;
		for (long[] column : input) {
			column[5] = column[0];
			column[7] = column[6];
		}
		return input;
	}

	private static void assertCommittedState(TripleStore store, Set<List<Long>> expected) throws IOException {
		store.getTxnManager().doWith((stack, txn) -> {
			assertState(LmdbPersistentAdjacency.openExisting(txn), txn, expected);
			return null;
		});
	}

	private static void assertState(LmdbPersistentAdjacency adjacency, long txn, Set<List<Long>> expected)
			throws IOException {
		assertThat(expected).hasSize(135);
		assertThat(adjacency.count(txn, true)).isEqualTo(expected.size());
		assertThat(adjacency.count(txn, false)).isEqualTo(1);
		assertThat(adjacency.predicateCount(txn, 20, true)).isEqualTo(134);
		assertThat(adjacency.predicateCount(txn, 30, true)).isEqualTo(1);
		assertThat(adjacency.contextTotal(txn, 0)).isEqualTo(133);
		assertThat(adjacency.contextTotal(txn, 7)).isEqualTo(2);
		assertThat(adjacency.contextTotal(txn, 9)).isEqualTo(1);
		assertThat(adjacency.contextCount(txn, 7, false)).isZero();
		assertThat(adjacency.isIdReferenced(txn, 2000)).isTrue();
		assertThat(adjacency.isIdReferenced(txn, 2001)).isTrue();
		for (boolean incoming : new boolean[] { false, true }) {
			try (RecordIterator rows = adjacency.scan(txn, -1, -1, -1, -1, true, incoming)) {
				Set<List<Long>> actual = new HashSet<>();
				for (long[] quad; (quad = rows.next()) != null;) {
					assertThat(actual.add(List.of(quad[0], quad[1], quad[2], quad[3]))).isTrue();
				}
				assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
			}
			try (RecordIterator rows = adjacency.scan(txn, -1, -1, -1, -1, false, incoming)) {
				assertThat(rows.next()).containsExactly(2001, 20, 9002, 9);
				assertThat(rows.next()).isNull();
			}
		}
	}
}
